<template><view class="announcements-box"><text class="announcement-title">学院通知</text><view class="announcement-body"><view v-if="items.length" :class="['notice-track',{'notice-still':items.length===1&&items[0].content.length<28}]"><button v-for="row in items" :key="row.id" role="button" class="notice-item" @click="selected=row">{{row.content}}</button></view><text v-if="failed" class="small">通知暂时加载失败，请稍后刷新。</text></view></view><view v-if="selected" class="notice-overlay" @click.self="selected=null"><view class="notice-dialog" role="dialog" aria-modal="true" aria-label="学院通知"><text class="notice-heading">学院通知</text><text class="notice-content">{{selected.content}}</text><button role="button" class="notice-close" @click="selected=null">我知道了</button></view></view></template>
<script setup>
import {inject,ref,onMounted,onUnmounted} from 'vue';import {api as defaultApi} from '../services/api.js';
const api=inject('portalClient',defaultApi);
const items=ref([]),failed=ref(false),selected=ref(null);let timer,disposed=false;
async function load(){try{const all=[];let page=1,total;do{const {data}=await api.request('/announcements?page='+page+'&pageSize=100');all.push(...data.items);total=data.total;page++;}while(all.length<total&&page<=1000);if(!disposed){items.value=all;failed.value=false;}}catch{if(!disposed)failed.value=true;}}
onMounted(()=>{load();timer=setInterval(load,30000);});onUnmounted(()=>{disposed=true;clearInterval(timer);});
</script>
<style scoped>.announcements-box{display:flex;align-items:center;gap:18px;background:#fff;border:1px solid #dde6df;border-left:4px solid #456b89;border-radius:10px;padding:15px 18px;margin-bottom:22px;min-height:56px}.announcement-title{font-weight:700;color:#111;flex-shrink:0}.announcement-body{flex:1;min-width:0;overflow:hidden;line-height:1.8}.notice-track{display:flex;width:max-content;gap:50px;animation:notice-scroll 28s linear infinite}.notice-track:hover,.notice-track:focus-within{animation-play-state:paused}.notice-still{animation:none}.notice-item{font-size:14px;padding:0;margin:0;background:none;color:#111;white-space:nowrap;border:0;line-height:1.8;text-align:left}.notice-item:after{border:0}.notice-overlay{position:fixed;inset:0;background:#102b4470;z-index:160;display:flex;align-items:center;justify-content:center;padding:24px}.notice-dialog{background:white;border-radius:14px;max-width:620px;width:100%;padding:28px}.notice-heading{display:block;font-size:21px;font-weight:700;color:#111;margin-bottom:20px}.notice-content{display:block;white-space:pre-wrap;line-height:1.9;color:#111;max-height:65vh;overflow:auto}.notice-close{background:#456b89;color:white;font-size:14px;margin-top:22px;line-height:2.8}@keyframes notice-scroll{0%,10%{transform:translateX(0)}95%,100%{transform:translateX(-80%)}}@media(prefers-reduced-motion:reduce){.notice-track{animation:none}.announcement-body{overflow:auto}}
@media(max-width:760px){.announcements-box{box-sizing:border-box;min-height:44px;padding:10px 12px;gap:12px;margin-bottom:14px;border-radius:8px;border-left-width:3px}.announcement-title,.notice-item{font-size:13px}.notice-dialog{padding:20px}.notice-heading{font-size:19px;margin-bottom:14px}}
</style>